export function searchAncestryFeats(query = '', ancestryFilter = '') {
    const q = String(query || '').trim().toLowerCase().replace(/ё/g, 'е');
    const anc = String(ancestryFilter || '').trim().toLowerCase().replace(/ё/g, 'е');
    let list = PF2E_ANCESTRY_FEATS;
    if (anc) {
        list = list.filter(f =>
            anc.includes(f.ancestryName.toLowerCase().replace(/ё/g, 'е')) ||
            anc.includes(f.ancestry.toLowerCase())
        );
    }
    if (!q) return list;
    return list.filter(f =>
        f.name.toLowerCase().replace(/ё/g, 'е').includes(q) ||
        f.ancestryName.toLowerCase().replace(/ё/g, 'е').includes(q)
    );
}